{
  "contract": "NeoCypherpunk",
  "closure": {
    "site_function": "feeClaim",
    "site_call": ".call",
    "functions": [
      "transfer",
      "transferFrom",
      "claimMarketingFees"
    ],
    "justification": "Includes all public/external functions that can be called during the callback window and affect 'pendingmarketingFees'."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom",
      "claimMarketingFees"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1,
      "claimMarketingFees": 1
    }
  },
  "phases": {
    "function": "feeClaim",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of pending marketing fees in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "pendingmarketingFees == _balances[address(this)] + inFlight",
    "stable_formula": "pendingmarketingFees == _balances[address(this)]",
    "kind": "additive"
  },
  "composition": {
    "target_property": "pendingmarketingFees <= _balances[address(this)]",
    "rule": "The exposure invariant ensures that pendingmarketingFees is correctly accounted for during reentrant calls, maintaining the target property."
  }
}
